DO $house$ DECLARE ac jsonb;pc jsonb;item record;changed integer:=0;receipts jsonb:='[]';job bigint;deadline timestamptz;BEGIN IF NOT pg_try_advisory_xact_lock(2026083000261022) THEN RETURN;END IF;SELECT to_jsonb(a),to_jsonb(p) INTO ac,pc FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p WHERE a.singleton AND p.singleton FOR SHARE OF a,p;SELECT jobid INTO job FROM cron.job WHERE jobname='top3000-closed-claim-housekeeping-v1';deadline:=least((ac->>'admitted_until')::timestamptz,(pc->>'deadline')::timestamptz,'2026-10-28T23:32:47.456756Z'::timestamptz);IF ac->>'owner_id' IS DISTINCT FROM 'top3000-completion-20261024-root-5db48b32d103' OR ac->>'owner_fence' IS DISTINCT FROM '3' OR ac->>'stop_generation' IS DISTINCT FROM '1' OR ac->>'scope_sha256' IS DISTINCT FROM '8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd' OR pc->>'scope_sha256' IS DISTINCT FROM ac->>'scope_sha256' OR ac->>'enabled' IS DISTINCT FROM 'true' OR ac->>'stopped' IS DISTINCT FROM 'false' OR ac->>'hold_reason' IS NOT NULL OR pc->>'enabled' IS DISTINCT FROM 'true' OR ac->>'admitted_until' IS NULL OR pc->>'deadline' IS NULL OR deadline IS NULL OR deadline<=clock_timestamp() THEN IF job IS NOT NULL THEN PERFORM cron.unschedule(job);END IF;RETURN;END IF;FOR item IN SELECT q.clearing_id,to_jsonb(q) prior_queue,e.event_id claim_event,r.event_id closure_event,r.at closure_at FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 q JOIN population_top3000_202608_202609_v1.pipeline_event e ON e.event_id::text=q.input_manifest->0->>'claim_event_id' JOIN LATERAL(SELECT z.event_id,z.at FROM population_top3000_202608_202609_v1.pipeline_event z WHERE z.event_id>e.event_id AND z.event='ENGINEERING_ASSIGNMENT_EFFECTS_RECONCILED_RELEASE_V5' AND z.details->>'claim_event_id'=e.event_id::text AND z.details->>'effects_known'='true' ORDER BY z.event_id DESC LIMIT 1)r ON true WHERE q.kind='CLAIM_RECONCILIATION' AND q.status='READY' AND q.attempts=0 AND q.claim_token_sha256 IS NULL AND q.owner_id=ac->>'owner_id' AND q.owner_fence=3 AND q.stop_generation=1 AND q.scope_sha256=ac->>'scope_sha256' AND jsonb_typeof(q.input_manifest)='array' AND CASE WHEN jsonb_typeof(q.input_manifest)='array' THEN jsonb_array_length(q.input_manifest) ELSE 0 END=1 AND q.input_manifest->0->>'claim_details_sha256'=encode(sha256(convert_to(e.details::text,'UTF8')),'hex') AND e.event='ENGINEERING_ASSIGNMENT_CLAIMED_V5' AND e.details->>'owner_id'=ac->>'owner_id' AND e.details->>'owner_fence'='3' AND e.details->>'stop_generation'='1' ORDER BY q.created_at,q.clearing_id LIMIT 16 FOR UPDATE OF q SKIP LOCKED LOOP UPDATE population_top3000_202608_202609_v1.continuation_clear_queue_v6 SET status='SUPERSEDED',last_receipt=coalesce(last_receipt,'{}'::jsonb)||jsonb_build_object('reason','EXACT_CLAIM_ALREADY_EFFECTS_RECONCILED','existing_release_event_id',item.closure_event,'claim_event_id',item.claim_event,'effects_known',true,'data_acceptance_changed',false,'new_execution_claimed',false,'housekeeping_revision','CLOSED_CLAIM_BOOKKEEPING_V1'),updated_at=clock_timestamp() WHERE clearing_id=item.clearing_id AND status='READY' AND attempts=0;IF FOUND THEN changed:=changed+1;receipts:=receipts||jsonb_build_array(jsonb_build_object('prior_queue',item.prior_queue,'release_event_id',item.closure_event,'release_at',item.closure_at));END IF;END LOOP;IF changed>0 THEN INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CLOSED_CLAIM_HOUSEKEEPING_APPLIED_V1',jsonb_build_object('actor','bounded_database_bookkeeping','owner_id',ac->>'owner_id','owner_fence',3,'stop_generation',1,'groups_superseded',changed,'prior_rows_and_existing_receipts',receipts,'max_groups',16,'new_source_or_quality_acceptance',false));END IF;IF job IS NOT NULL AND NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='CLOSED_CLAIM_HOUSEKEEPING_TIMER_VERIFIED_V1' AND details->>'job_id'=job::text) THEN INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CLOSED_CLAIM_HOUSEKEEPING_TIMER_VERIFIED_V1',jsonb_build_object('job_id',job,'backend_pid',pg_backend_pid(),'application_name',current_setting('application_name'),'groups_superseded',changed,'source_acquisition_claimed',false,'future_check_interval','5 minutes','hard_not_after',deadline));PERFORM cron.alter_job(job,schedule=>'*/5 * * * *');END IF;END $house$;